 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;static int passed,failed;static Type fix;static List<Tuple<Combat.CombatUnit.EstimatedState,Effect>> projected;
 static int Main(string[] a){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{var name=new AssemblyName(e.Name).Name+".dll";var p=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name);if(!File.Exists(p))p=Path.Combine(a[0],"Star Renegades_Data/Managed",name);return File.Exists(p)?Assembly.LoadFrom(p):null;};return Run();}
 [MethodImpl(MethodImplOptions.NoInlining)] static int Run(){projected=new List<Tuple<Combat.CombatUnit.EstimatedState,Effect>>();fix=typeof(ComboEffectTests).Assembly.GetType("SRBugfix.ComboEffectFix");var h=new Harmony("test.combo-effect-routing");if(fix!=null){Invoke(fix,"Install",h);Enabled(true);}h.Patch(typeof(Combat.CombatUnit.EstimatedState).GetMethod("ApplyEffect"),prefix:new HarmonyMethod(typeof(ComboEffectTests).GetMethod("ObserveProjection",F)));try{
 Test("ShadowPuppetsNativeExecutionGrantsDarkParagonParticipantOnly",()=>{var f=new Fixture();var r=f.Execute();Check(r.Count(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.effect.ID=="hDarSpeCombo"&&ReferenceEquals(v.target,f.Partner))==1,"Dark Paragon participant received no instant attack effect");Check(f.Applications.Count(a=>a.Item1==f.Partner&&a.Item2.ID=="hDarSpeCombo")==1,"native effect event did not target participant");Check(!f.Applications.Any(a=>a.Item1==f.Third&&a.Item2.ID=="hDarSpeCombo"),"third party received effect");Check(f.Applications.Any(a=>a.Item1==f.Source&&a.Item2.ID=="hSpeStealth"),"Spectre lost normal stealth");Check(r.Any(v=>v.type==Combat.CombatPowerResult.Type.GainShield&&v.target==f.Source&&v.shieldAmount==10),"normal Spectre shields changed");});
 Test("AllTwentySpectreAndDarkParagonVariantPairsRouteSelectedPartner",()=>{foreach(var s in new[]{"hSpe","hSpeSab","hSpeAeg","hSpeVar","hSpePar"})foreach(var p in new[]{"hDar","hDarSab","hDarCom","hDarVar"}){var f=new Fixture(s,p);var r=f.Execute();Check(r.Count(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.effect.ID=="hDarSpeCombo"&&v.target==f.Partner)==1,"variant failed "+s+" / "+p);Check(!r.Any(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.effect.ID=="hDarSpeCombo"&&v.target==f.Third),"third-party variant received effect");}});
 Test("DisabledHookPreservesNativeMissingEffectAndSpectreStealth",()=>{Enabled(false);try{var f=new Fixture();var r=f.Execute();Check(!r.Any(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.effect.ID=="hDarSpeCombo"),"disabled hook routed effect");Check(f.Applications.Any(a=>a.Item1==f.Source&&a.Item2.ID=="hSpeStealth"),"disabled native stealth lost");}finally{Enabled(true);}});
 Test("MissingCachedPartnerDoesNotGrantAnyDarkParagonEffect",()=>{var f=new Fixture();Set(f.Execution,"comboLink",null);Check(!f.Execute().Any(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.effect.ID=="hDarSpeCombo"),"missing partner routed to ally");});
 Test("SelectedPartnerImmunityRetainsNativeEffectGate",()=>{var f=new Fixture();((GameElementCollection<Effect>)Get(f.Partner.Unit,"effectImmunities")).Add(f.Instant);Check(!f.Execute().Any(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.effect.ID=="hDarSpeCombo"),"effect immunity ignored");});
 Test("SelectedPartnerMissingRequiredTagCannotReceiveEffect",()=>{var f=new Fixture();((HashSet<string>)Get(f.Partner.Unit,"tags")).Remove("hDarUnit");Check(!f.Execute().Any(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.effect.ID=="hDarSpeCombo"),"required tag bypassed");});
 Test("DeadSelectedPartnerDoesNotRedirectToLivingThirdParty",()=>{var f=new Fixture();Set(f.Partner,"state",Combat.CombatUnit.UnitState.Dead);Check(!f.Execute().Any(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.effect.ID=="hDarSpeCombo"),"dead partner rerouted");});
 Test("DifferentPowerAndComboCannotUseShadowRouting",()=>{var f=new Fixture();Set(f.Execution.power.Power.Power,"id","hComSpeCombo");Check(!f.Execute().Any(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.effect.ID=="hDarSpeCombo"),"unrelated combo altered");});
 Test("DifferentEffectCannotUseShadowRouting",()=>{var f=new Fixture();Set(f.Instant,"id","otherInstant");Check(!f.Execute().Any(v=>v.type==Combat.CombatPowerResult.Type.ApplyEffect&&v.target==f.Partner),"other effect routed");});
 Test("EffectDefinitionKeepsNativeDurationAndOneAttackCancellation",()=>{var f=new Fixture();f.Execute();Check(f.Instant.EffectData.duration==-1&&f.Instant.EffectData.cancelledAfterNumAttacks==1&&!f.Instant.EffectData.cancelledOnInterrupt&&f.Instant.EffectData.requiredUnitTags.SequenceEqual(new[]{"hDarUnit"}),"effect policy changed");Check(f.Instant.PowerModifiers.Count==1&&f.Instant.PowerModifiers[0].ModifierData.setExecution==1&&f.Instant.PowerModifiers[0].ModifierData.modExecution==-1,"instant modifier changed");});
 Test("NativeInstantModifierStillRequiresAttackAndCanHastenTags",()=>{var f=new Fixture();var pd=new PowerData{id="ordinary",execution=30,tags=new[]{"attack","canhasten"}};Arrays(pd);var p=Blank<Power>();Init(p,f.Game,pd.id);Set(p,"powerData",pd);var before=new UnitPower(f.Partner.Unit,p);Check(before.ExecutionTime==30,"ordinary action fixture");((List<PowerModifier>)Get(f.Partner.Unit,"otherPowerModifiers")).Add(f.Instant.PowerModifiers[0]);before.RecalculateValues();Check(before.ExecutionTime==0,"native instant modifier not used");pd.tags=new[]{"attack"};before.RecalculateValues();Check(before.ExecutionTime==30,"native canhasten requirement changed");});
 Test("DryRunValidationInstallsNoHooks",()=>{Check(fix!=null,"fix missing");int n=Harmony.GetAllPatchedMethods().Count();Invoke(fix,"ValidateTargets");Check(Harmony.GetAllPatchedMethods().Count()==n,"validation installed hooks");});
 Test("NativeForecastRoutesExistingEffectToSelectedPartnerWithoutLiveMutation",()=>{var f=new Fixture();var states=f.Forecast();Check(projected.Count(p=>p.Item1.Unit==f.Partner&&p.Item2==f.Instant)==1,"forecast omitted selected partner effect");Check(!projected.Any(p=>p.Item1.Unit==f.Third&&p.Item2==f.Instant),"forecast routed third-party effect");Check(projected.Any(p=>p.Item1.Unit==f.Source&&p.Item2.ID=="hSpeStealth"),"forecast source stealth changed");Check(states[f.Source].shield==10,"native forecast source shields changed");Check(f.Source.Unit.CurrentShield==0&&f.Partner.Unit.Effects.Count==0&&f.Source.Unit.Effects.Count==0,"forecast mutated live units");});
 Test("ForecastImmunityAndRequiredTagGatePreventPartnerProjection",()=>{var f=new Fixture();((GameElementCollection<Effect>)Get(f.Partner.Unit,"effectImmunities")).Add(f.Instant);f.Forecast();Check(!projected.Any(p=>p.Item2==f.Instant),"forecast immunity bypassed");var g=new Fixture();((HashSet<string>)Get(g.Partner.Unit,"tags")).Remove("hDarUnit");g.Forecast();Check(!projected.Any(p=>p.Item2==g.Instant),"forecast required tag bypassed");});
 Test("DisabledForecastPreservesOriginalRecipientFailure",()=>{Enabled(false);try{var f=new Fixture();f.Forecast();Check(!projected.Any(p=>p.Item2==f.Instant),"disabled forecast altered routing");}finally{Enabled(true);}});
 Test("SharedProjectedEffectsReceivePartnerEffectAndPreserveLiveUnits",()=>{SRBugfix.ProjectedEffectFix.Install(h);SRBugfix.ProjectedEffectFix.Enabled=true;try{var f=new Fixture();var states=f.Forecast();Check(SRBugfix.ProjectedEffectFix.EffectsForEstimate(f.Partner.Unit,states[f.Partner]).Any(e=>e.Effect==f.Instant),"shared projection lost routed partner effect");Check(!SRBugfix.ProjectedEffectFix.EffectsForEstimate(f.Source.Unit,states[f.Source]).Any(e=>e.Effect==f.Instant),"shared projection misrouted to Spectre");Check(f.Partner.Unit.Effects.Count==0&&f.Source.Unit.Effects.Count==0,"shared forecast mutated live effects");}finally{SRBugfix.ProjectedEffectFix.Enabled=false;}});
 Test("NativeLiveEffectConsumerMakesPartnerNextAttackInstant",()=>{var f=new Fixture();f.LivePartner();var r=f.Execute();Invoke(f.Combat,"HandlePowerResults",f.Execution,r);Check(f.Partner.Unit.HasEffect(f.Instant),"native live Unit.AddEffect not reached");Check(f.Partner.Unit.Powers["ordinary"].ExecutionTime==0,"native live next attack not instant");Check(!f.Third.Unit.HasEffect(f.Instant),"third party live effect changed");});
 Test("NativeOriginalShadowEffectSurvivesOutgoingAttackWithoutWipeTag",()=>{var f=new Fixture();f.Instant.EffectData.tags=new string[0];((UnityEngine.ISerializationCallbackReceiver)f.Instant.EffectData).OnAfterDeserialize();f.LivePartner();f.Execute();f.NextAttack();Check(f.Partner.Unit.HasEffect(f.Instant)&&f.Partner.Unit.Powers["ordinary"].ExecutionTime==0,"original effect does not persist as characterized");});
 Test("NativeWipedByAttackingTagConsumesInstantEffectAfterNextAttack",()=>{var f=new Fixture();f.Instant.EffectData.tags=new[]{"wipedByAttacking"};((UnityEngine.ISerializationCallbackReceiver)f.Instant.EffectData).OnAfterDeserialize();f.LivePartner();f.Execute();Check(f.Partner.Unit.Powers["ordinary"].ExecutionTime==0,"first attack no longer instant");f.NextAttack();Check(!f.Partner.Unit.HasEffect(f.Instant)&&f.Partner.Unit.Powers["ordinary"].ExecutionTime==30,"native outgoing action did not consume tagged instant effect");});
 Test("ConfiguredShadowEffectIsConsumedAfterNextAttack",()=>{var f=new Fixture();f.LivePartner();f.Execute();Check(f.Partner.Unit.Powers["ordinary"].ExecutionTime==0,"combo consumed its own granted effect");f.NextAttack();Check(!f.Partner.Unit.HasEffect(f.Instant)&&f.Partner.Unit.Powers["ordinary"].ExecutionTime==30,"missing wipedByAttacking tag permits repeated instant attacks");});
 Test("DefendAndNonattackDoNotConsumeConfiguredInstantEffect",()=>{var f=new Fixture();f.LivePartner();f.Execute();f.Nonattack(true);f.Nonattack(false);Check(f.Partner.Unit.HasEffect(f.Instant)&&f.Partner.Unit.Powers["ordinary"].ExecutionTime==0,"nonattack consumed next attack effect");f.NextAttack();Check(!f.Partner.Unit.HasEffect(f.Instant)&&f.Partner.Unit.Powers["ordinary"].ExecutionTime==30,"attack after defend did not consume instant");});
 Test("AllTwentyVariantPairsReceiveAndConsumeExactlyOneNativeInstantAttack",()=>{foreach(var s in new[]{"hSpe","hSpeSab","hSpeAeg","hSpeVar","hSpePar"})foreach(var p in new[]{"hDar","hDarSab","hDarCom","hDarVar"}){var f=new Fixture(s,p);f.LivePartner();var r=f.Execute();Invoke(f.Combat,"HandlePowerResults",f.Execution,r);Check(f.Partner.Unit.Powers["ordinary"].ExecutionTime==0&&f.Partner.Unit.Effects.Count(e=>e.Effect==f.Instant)==1,"variant first attack failed "+s+" / "+p);f.Nonattack(true);Check(f.Partner.Unit.HasEffect(f.Instant),"variant defend consumed effect");f.NextAttack();Check(f.Partner.Unit.Powers["ordinary"].ExecutionTime==30&&!f.Partner.Unit.HasEffect(f.Instant),"variant later attack remained instant");f.NextAttack();Check(f.Partner.Unit.Powers["ordinary"].ExecutionTime==30&&!f.Third.Unit.HasEffect(f.Instant),"later attack or third party changed");}});
 Test("ForecastFaultLeavesLiveUnitsUntouchedAndLaterForecastWorks",()=>{SRBugfix.ProjectedEffectFix.Enabled=true;try{var f=new Fixture();var states=f.ForecastStates();Set(f.Game,"currentDifficulty",null);bool threw=false;try{f.ForecastInto(states);}catch(NullReferenceException){threw=true;}Check(threw,"native fault fixture did not throw");Check(f.Partner.Unit.Effects.Count==0&&f.Source.Unit.Effects.Count==0&&f.Source.Unit.CurrentShield==0,"forecast fault mutated live units");Set(f.Game,"currentDifficulty",new DifficultyData{id="default"});f.ForecastInto(states);Check(SRBugfix.ProjectedEffectFix.EffectsForEstimate(f.Partner.Unit,states[f.Partner]).Count(e=>e.Effect==f.Instant)==1,"forecast failed after native exception");Check(f.Partner.Unit.Effects.Count==0,"later forecast mutated live effects");}finally{SRBugfix.ProjectedEffectFix.Enabled=false;}});
 Test("SharedForecastConsumesProjectedInstantOnlyAfterAttack",()=>{SRBugfix.ProjectedEffectFix.Enabled=true;try{var f=new Fixture();f.LivePartner();var states=f.Forecast();Check(SRBugfix.ProjectedEffectFix.EffectsForEstimate(f.Partner.Unit,states[f.Partner]).Any(e=>e.Effect==f.Instant),"initial projected instant missing");f.ForecastNext(states,true);Check(SRBugfix.ProjectedEffectFix.EffectsForEstimate(f.Partner.Unit,states[f.Partner]).Any(e=>e.Effect==f.Instant),"projected defend consumed instant");f.ForecastNext(states,false);Check(!SRBugfix.ProjectedEffectFix.EffectsForEstimate(f.Partner.Unit,states[f.Partner]).Any(e=>e.Effect==f.Instant),"projected instant persisted after source attack");Check(f.Partner.Unit.Effects.Count==0&&f.Source.Unit.Effects.Count==0&&f.Partner.Unit.Powers["ordinary"].ExecutionTime==30,"projected cancellation mutated live effect or timing");}finally{SRBugfix.ProjectedEffectFix.Enabled=false;}});
 Test("ProjectedInstantSurvivesNativeForecastFaultThenCancelsOnSuccessfulRetry",()=>{SRBugfix.ProjectedEffectFix.Enabled=true;try{var f=new Fixture();f.LivePartner();var states=f.Forecast();Set(f.Game,"currentDifficulty",null);bool threw=false;try{f.ForecastNext(states,false);}catch(NullReferenceException){threw=true;}Check(threw,"future action fault did not throw");Check(SRBugfix.ProjectedEffectFix.EffectsForEstimate(f.Partner.Unit,states[f.Partner]).Any(e=>e.Effect==f.Instant),"failed future forecast consumed instant");Set(f.Game,"currentDifficulty",new DifficultyData{id="default"});f.ForecastNext(states,false);Check(!SRBugfix.ProjectedEffectFix.EffectsForEstimate(f.Partner.Unit,states[f.Partner]).Any(e=>e.Effect==f.Instant),"successful retry did not consume instant");Check(f.Partner.Unit.Effects.Count==0&&f.Partner.Unit.Powers["ordinary"].ExecutionTime==30,"retry mutated live unit");}finally{SRBugfix.ProjectedEffectFix.Enabled=false;}});
 }finally{h.UnpatchAll(h.Id);Enabled(false);}Console.WriteLine("RESULT "+passed+" passed, "+failed+" failed");return failed==0?0:1;}
 static void Enabled(bool value){if(fix!=null)fix.GetField("Enabled",F).SetValue(null,value);}
 static void ObserveProjection(Combat.CombatUnit.EstimatedState __instance,Effect __0){projected.Add(Tuple.Create(__instance,__0));}
 class Fixture{
 public SRRWGame Game;public Combat Combat;public Combat.CombatUnit Source,Partner,Third;public Combat.CombatPowerExecution Execution;public Effect Instant;public List<Tuple<Combat.CombatUnit,Effect>> Applications=new List<Tuple<Combat.CombatUnit,Effect>>();
 public Fixture(string sourceID="hSpe",string partnerID="hDar"){Game=Blank<SRRWGame>();Init(Game,Game,"game");Set(Game,"currentDifficulty",new DifficultyData{id="default"});var gd=new GameData();Init(gd,Game,"data");Set(gd,"GameRulesData",new GameRulesData());Set(Game,"gameData",gd);Combat=Blank<Combat>();Init(Combat,Game,"combat");Set(Combat,"unitsByPosition",new List<string>(new string[12]));var team=Blank<Combat.CombatTeam>();Init(team,Game,"team");Set(team,"combat",Combat);Set(Combat,"playerTeam",team);Source=Unit(sourceID,"hSpeUnit",Combat.Position.A1,team);Partner=Unit(partnerID,"hDarUnit",Combat.Position.A2,team);Third=Unit(partnerID=="hDarSab"?"hDarVar":"hDarSab","hDarUnit",Combat.Position.A3,team);var squad=Blank<Squad>();Init(squad,Game,"squad");Set(squad,"units",new[]{Source.Unit,Partner.Unit,Third.Unit,null,null,null});foreach(var cu in new[]{Source,Partner,Third})Set(cu.Unit,"squad",squad);
 var instant=MakeEffect("hDarSpeCombo","hDarUnit");Instant=instant;instant.EffectData.tags=ShadowTags();((UnityEngine.ISerializationCallbackReceiver)instant.EffectData).OnAfterDeserialize();instant.EffectData.duration=-1;instant.EffectData.cancelledAfterNumAttacks=1;var md=new PowerModifierData{id="eqpInstantAttacks",tags=new[]{"attack","canhasten"},setExecution=1,modExecution=-1};Arrays(md);var modifier=Blank<PowerModifier>();Init(modifier,Game,md.id);Set(modifier,"modifierData",md);instant.PowerModifiers.Add(modifier);var stealth=MakeEffect("hSpeStealth","hSpeUnit");stealth.EffectData.duration=-1;stealth.EffectData.cancelledAfterNumAttacks=1;stealth.EffectData.isUntargetable=true;
 var pd=new PowerData{id="hDarSpeCombo",tags=new[]{"combo","nonMode"},target="Self",hostility="Ally",range="Any",shieldGain=10,freePower=true,effects=new[]{"hDarSpeCombo"},sourceEffects=new[]{"hSpeStealth"},cancelEffectsByTag=new[]{"dot"},cancelSourceEffectsByTag=new[]{"wipedByAction"},deactivatesPowersOnUse=new[]{"hDarSpeCombo"},onUseActivationCount=1};Arrays(pd);var p=Blank<Power>();Init(p,Game,pd.id);Set(p,"powerData",pd);((Dictionary<string,Power>)Get(Game,"powers"))[p.ID]=p;var combo=Blank<Combo>();Init(combo,Game,pd.id);Set(combo,"comboPower",p);Set(combo,"primaryUnitID",Source.ID);Set(combo,"secondaryUnitID",Partner.ID);Set(combo,"comboData",new ComboData{id=pd.id,primaryUnitClassID="hSpe",secondaryUnitClassID="hDar",comboPower=pd.id});var cps=new List<Combat.CombatUnitPower>();foreach(var cu in new[]{Source,Partner}){var up=new UnitPower(cu.Unit,p);Set(up,"combo",combo);Set(up,"id",pd.id);cu.Unit.Powers.Add(up);var cp=Blank<Combat.CombatUnitPower>();Init(cp,Game,pd.id);Set(cp,"unit",cu);Set(cp,"combat",Combat);Set(cp,"power",up);((GameElementCollection<Combat.CombatUnitPower>)Get(cu,"powers")).Add(cp);cps.Add(cp);}Execution=new Combat.CombatPowerExecution(Combat,cps[0],Source,new Combat.CombatTime(0,0));
 Combat.OnEffectApplied+=(u,e,s,x)=>Applications.Add(Tuple.Create(u,e));var schedule=typeof(Combat).GetNestedType("CombatSchedule",F);Set(Combat,"schedule",Activator.CreateInstance(schedule,F,null,new object[]{Combat,null},null));}
 Combat.CombatUnit Unit(string id,string tag,Combat.Position pos,Combat.CombatTeam team){var u=Blank<Unit>();Init(u,Game,id);Set(u,"unitData",new UnitData{id=id});Set(u,"unitClassData",new UnitClassData{id=tag=="hSpeUnit"?"hSpe":"hDar"});Set(u,"tags",new HashSet<string>{"hero",tag});Set(u,"currentHealth",100);Set(u,"maximumHealth",new ModifiedValue(100));Set(u,"damage",new ModifiedValue(100));Set(u,"speed",new ModifiedValue(100));Set(u,"shieldCap",new ModifiedValue(50));var cu=Blank<Combat.CombatUnit>();Init(cu,Game,id);Set(cu,"unit",u);Set(cu,"combat",Combat);Set(cu,"team",team);Set(cu,"position",pos);Set(cu,"state",Combat.CombatUnit.UnitState.Ready);((GameElementCollection<Combat.CombatUnit>)Get(team,"units")).Add(cu);((GameElementCollection<Combat.CombatUnit>)Get(Combat,"units")).Add(cu);((List<string>)Get(Combat,"unitsByPosition"))[(int)pos]=id;return cu;}
 Effect MakeEffect(string id,string tag){var d=new EffectData{id=id,requiredUnitTags=new[]{tag},ignoreShield=true,ignoreArmor=true};Arrays(d);((UnityEngine.ISerializationCallbackReceiver)d).OnAfterDeserialize();var e=Blank<Effect>();Init(e,Game,id);Set(e,"effectData",d);((Dictionary<string,Effect>)Get(Game,"effects"))[id]=e;return e;}
 public List<Combat.CombatPowerResult> Execute(){var ev=Blank<Combat.ExecutePowerEvent>();Init(ev,Game,"event");Set(ev,"combat",Combat);Set(ev,"powerExecution",Execution);var r=new List<Combat.CombatPowerResult>();Check((bool)Invoke(ev,"CalculateResults",Execution,r,null),"native execution failed");return r;}
 public Dictionary<Combat.CombatUnit,Combat.CombatUnit.EstimatedState> Forecast(){projected.Clear();var state=new Combat.CombatUnit.EstimatedState(Source);state.powerExecutionTime=new Combat.CombatTime(0,0);state.EstimateSourceEffects(Execution.power);var states=new Dictionary<Combat.CombatUnit,Combat.CombatUnit.EstimatedState>{{Source,state}};var results=new Dictionary<Combat.CombatUnit,Combat.UnitResults>();Invoke(Combat,"EstimatePowerAgainstTargets",states,Execution.power,results,new List<Combat.CombatUnit>{Source},true,true,null,null);return states;}
 public Dictionary<Combat.CombatUnit,Combat.CombatUnit.EstimatedState> ForecastStates(){var state=new Combat.CombatUnit.EstimatedState(Source);state.powerExecutionTime=new Combat.CombatTime(0,0);return new Dictionary<Combat.CombatUnit,Combat.CombatUnit.EstimatedState>{{Source,state}};}
 public void ForecastInto(Dictionary<Combat.CombatUnit,Combat.CombatUnit.EstimatedState> states){Invoke(Combat,"EstimatePowerAgainstTargets",states,Execution.power,new Dictionary<Combat.CombatUnit,Combat.UnitResults>(),new List<Combat.CombatUnit>{Source},true,true,null,null);}
 public void ForecastNext(Dictionary<Combat.CombatUnit,Combat.CombatUnit.EstimatedState> states,bool defend){Combat.CombatUnitPower cp;if(defend){var pd=new PowerData{id="hDarDefend",target="Self",hostility="Ally",execution=1,tags=new[]{"hDef","defend","noaim","1hit"}};Arrays(pd);var p=Blank<Power>();Init(p,Game,pd.id);Set(p,"powerData",pd);cp=new Combat.CombatUnitPower(Combat,Partner,new UnitPower(Partner.Unit,p));}else{cp=new Combat.CombatUnitPower(Combat,Partner,Partner.Unit.Powers["ordinary"]);}Invoke(Combat,"EstimatePowerAgainstTargets",states,cp,new Dictionary<Combat.CombatUnit,Combat.UnitResults>(),new List<Combat.CombatUnit>{Partner},true,true,null,null);}
 public void LivePartner(){var inventory=Blank<EquipmentInventory>();Init(inventory,Game,"inventory");Set(Partner.Unit,"inventory",inventory);var pd=new PowerData{id="ordinary",execution=30,target="Self",hostility="Ally",tags=new[]{"attack","canhasten"},cancelSourceEffectsByTag=new[]{"wipedByAttacking","wipedByAction"}};Arrays(pd);var p=Blank<Power>();Init(p,Game,pd.id);Set(p,"powerData",pd);((Dictionary<string,Power>)Get(Game,"powers"))[pd.id]=p;var ud=(UnitData)Get(Partner.Unit,"unitData");ud.tags=new[]{"hero","hDarUnit"};Arrays(ud);var uc=Partner.Unit.UnitClassData;Arrays(uc);uc.health=100;uc.shieldCap=50;uc.speed=100;uc.damage=100;uc.powers=new[]{"ordinary"};((GameElementCollection<Combo>)Get(Partner.Unit,"unlockedCombos")).Add(Execution.power.Power.Combo);var up=new UnitPower(Partner.Unit,p);Set(up,"id","ordinary");Partner.Unit.Powers.Add(up);Invoke(Partner,"ConnectToCombat",Combat);}
 public void NextAttack(){var cp=new Combat.CombatUnitPower(Combat,Partner,Partner.Unit.Powers["ordinary"]);var ex=new Combat.CombatPowerExecution(Combat,cp,Partner,new Combat.CombatTime(1,0));var ev=Blank<Combat.ExecutePowerEvent>();Init(ev,Game,"next");Set(ev,"combat",Combat);Set(ev,"powerExecution",ex);var results=new List<Combat.CombatPowerResult>();Check((bool)Invoke(ev,"CalculateResults",ex,results,null),"native next attack failed");Invoke(Combat,"HandlePowerResults",ex,results);}
 public void Nonattack(bool defend){var pd=new PowerData{id=defend?"hDarDefend":"nonattack",execution=1,target="Self",hostility="Ally",tags=defend?new[]{"hDef","defend","noaim","1hit"}:new[]{"buff"},cancelSourceEffectsByTag=defend?new string[0]:new[]{"wipedByAction"}};Arrays(pd);var p=Blank<Power>();Init(p,Game,pd.id);Set(p,"powerData",pd);var cp=new Combat.CombatUnitPower(Combat,Partner,new UnitPower(Partner.Unit,p));var ex=new Combat.CombatPowerExecution(Combat,cp,Partner,new Combat.CombatTime(1,0));var ev=Blank<Combat.ExecutePowerEvent>();Init(ev,Game,"nonattack");Set(ev,"combat",Combat);Set(ev,"powerExecution",ex);var results=new List<Combat.CombatPowerResult>();Check((bool)Invoke(ev,"CalculateResults",ex,results,null),"native nonattack failed");Invoke(Combat,"HandlePowerResults",ex,results);}
