 static void Arrays(object o){foreach(var f in o.GetType().GetFields(F))if(f.FieldType.IsArray&&f.GetValue(o)==null)f.SetValue(o,Array.CreateInstance(f.FieldType.GetElementType(),0));}
 static string[] ShadowTags(){
#if BASELINE_COMBO_DATA
 return new string[0];
#else
 return new[]{"wipedByAttacking"};
#endif
 }
 static T Blank<T>(){return (T)FormatterServices.GetUninitializedObject(typeof(T));}
 static void Init(object o,SRRWGame g,string id){if(o is GameElement){Set(o,"game",g);Set(o,"id",id);}for(Type t=o.GetType();t!=null;t=t.BaseType)foreach(var f in t.GetFields(F|BindingFlags.DeclaredOnly)){if(f.FieldType==typeof(ModifiedValue))f.SetValue(o,new ModifiedValue(0));else if(typeof(Delegate).IsAssignableFrom(f.FieldType)){var invoke=f.FieldType.GetMethod("Invoke");if(invoke.ReturnType==typeof(void)){var dm=new DynamicMethod("noop",typeof(void),invoke.GetParameters().Select(p=>p.ParameterType).ToArray());dm.GetILGenerator().Emit(OpCodes.Ret);f.SetValue(o,dm.CreateDelegate(f.FieldType));}}else if(f.FieldType.IsGenericType){var d=f.FieldType.GetGenericTypeDefinition();if(d==typeof(GameElementCollection<>))f.SetValue(o,Activator.CreateInstance(f.FieldType,new object[]{null}));else if(d==typeof(HashSet<>)||d==typeof(Dictionary<,>)||d==typeof(List<>))f.SetValue(o,Activator.CreateInstance(f.FieldType));}}}
 static object Get(object o,string n){for(Type t=o.GetType();t!=null;t=t.BaseType){var f=t.GetField(n,F|BindingFlags.DeclaredOnly)??t.GetField("<"+n+">k__BackingField",F|BindingFlags.DeclaredOnly);if(f!=null)return f.GetValue(o);}throw new Exception("missing field "+n);}
 static void Set(object o,string n,object v){for(Type t=o.GetType();t!=null;t=t.BaseType){var f=t.GetField(n,F|BindingFlags.DeclaredOnly)??t.GetField("<"+n+">k__BackingField",F|BindingFlags.DeclaredOnly);if(f!=null){f.SetValue(o,v);return;}}throw new Exception("missing field "+n+" on "+o.GetType());}
 static object Invoke(object o,string n,params object[] a){try{return (o is Type?(Type)o:o.GetType()).GetMethod(n,F).Invoke(o is Type?null:o,a);}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Test(string n,Action a){try{a();passed++;Console.WriteLine("PASS "+n);}catch(Exception e){failed++;Console.WriteLine("FAIL "+n+": "+e);}}
}
